const level = 'module'

function outer(): string {
  const level = 'outer'          // shadows the module-level name
  function inner(): string {
    return level                 // found one step out: 'outer'
  }
  return inner()
}

function caller(): string {
  const level = 'caller'         // irrelevant: lookup is lexical
  return outer()
}
console.log(caller())            // 'outer'

interface Counter { next(): number; peek(): number; reset(): number }

function makeCounter(start = 0, step = 1): Counter {
  let value = start                 // private: only these three functions see it
  return {
    next: () => (value += step),
    peek: () => value,
    reset: () => (value = start),
  }
}

const a = makeCounter()
const b = makeCounter(10, 5)
a.next(); a.next()
console.log(a.peek(), b.next())     // 2 15

function once<A extends unknown[], R>(fn: (...args: A) => R): (...args: A) => R {
  let done: { value: R } | undefined     // the box survives between calls
  return (...args: A): R => {
    if (done === undefined) done = { value: fn(...args) }
    return done.value
  }
}

const init = once((name: string) => `hello ${name}`)
console.log(init('ann'), init('bo'))   // hello ann hello ann

const dir = 'up'                    // type 'up'
let mode = 'up'                     // type string
const cfg = { dir: 'up' }           // { dir: string }
const fixed = { dir: 'up' } as const // { readonly dir: 'up' }

function label(id: string | number): () => string {
  const key = typeof id === 'number' ? String(id) : id
  return () => key.toUpperCase()    // key is string: const narrowing is stable
}

