function debounce<A extends unknown[]>(fn: (...args: A) => void, waitMs: number): (...args: A) => void {
  let timer: ReturnType<typeof setTimeout> | undefined   // private to this debounced copy
  return (...args: A): void => {
    clearTimeout(timer)                                 // cancel the pending call, if any
    timer = setTimeout(() => fn(...args), waitMs)       // args captured per call
  }
}

const saved: string[] = []
const save = debounce((text: string) => { saved.push(text) }, 20)
save('h'); save('he'); save('hel')
setTimeout(() => console.log(saved.join(',')), 50)     // hel

