type Op =
  | [action: 'make', name: string, start?: number, step?: number]
  | [action: 'next' | 'peek' | 'reset', name: string]

interface Counter {
  next(): number
  peek(): number
  reset(): number
}

function makeCounter(start = 0, step = 1): Counter {
  let value = start
  return {
    next: () => (value += step),
    peek: () => value,
    reset: () => (value = start),
  }
}

function runCounters(ops: Op[]): (number | null)[] {
  const counters = new Map<string, Counter>()
  const out: (number | null)[] = []
  for (const op of ops) {
    if (op[0] === 'make') {
      const [, name, start, step] = op
      counters.set(name, makeCounter(start, step))
      continue
    }
    const [action, name] = op
    const counter = counters.get(name)
    out.push(counter ? counter[action]() : null)
  }
  return out
}

The only real change is where `value` lives. Declared inside `makeCounter`, it belongs to that call's environment, so every counter gets its own private variable and the returned arrows are its only way in. Default parameters turn a missing `start` or `step` (a hole in the tuple, so `undefined`) into 0 and 1. The `Op` type is a union of labelled tuples, so checking `op[0] === 'make'` narrows the tuple and `counter[action]` is known to be one of the three methods. The `Map` lookup gives `undefined` for an unknown name, which becomes `null` in the output. Each op is O(1), so the whole run is O(ops).

