function once<A extends unknown[], R>(fn: (...args: A) => R): (...args: A) => R {
  let done: { value: R } | undefined
  return (...args: A): R => {
    if (done === undefined) done = { value: fn(...args) }
    return done.value
  }
}

function squareOnce(inputs: number[]): { results: number[]; calls: number } {
  let calls = 0
  const square = once((x: number): number => {
    calls++
    return x * x
  })
  const results = inputs.map(x => square(x))
  return { results, calls }
}

function memoize<A extends unknown[], R>(fn: (...args: A) => R, keyOf: (...args: A) => string): (...args: A) => R {
  const cache = new Map<string, { value: R }>()
  return (...args: A): R => {
    const key = keyOf(...args)
    const hit = cache.get(key)
    if (hit) return hit.value
    const value = fn(...args)
    cache.set(key, { value })
    return value
  }
}

function pathStats(queries: [number, number][]): { results: number[]; computed: number } {
  let computed = 0
  const paths: (rows: number, cols: number) => number = memoize(
    (rows: number, cols: number): number => {
      computed++
      if (rows < 0 || cols < 0) return 0
      if (rows === 0 || cols === 0) return 1
      return paths(rows - 1, cols) + paths(rows, cols - 1)
    },
    (rows, cols) => `${rows},${cols}`,
  )
  const results = queries.map(([rows, cols]) => paths(rows, cols))
  return { results, computed }
}

